const{execSync:execSync}=require("child_process"),path=require("path"),fs=require("fs"),MIGRATION_ROOT=__dirname,steps=[{name:"1. Şube Migrasyonu (migrate_tenants.js)",command:"node migrate_tenants.js",description:"MSSQL SUBE verilerini sys_tenants tablosuna aktarır."},{name:"2. MySQL Şema Hazırlığı (prepare_mysql_schema.js)",command:"node migration/prepare_mysql_schema.js",description:"Legacy sütunları (legacy_id, legacy_visit_id) hazırlar."},{name:"3. MSSQL Veri Çıkarma (extract_mssql.js)",command:"node migration/extract_mssql.js",description:"MSSQL verilerini okur ve json dosyasına kaydeder."},{name:"4. MySQL Veri Yükleme (load_mysql.js)",command:"node migration/load_mysql.js",description:"JSON verilerini MySQL veritabanına yükler."},{name:"5. Branş Verileri Birleştirme (merge_specialty_data.js)",command:"node merge_specialty_data.js",description:"Laboratuvar ve Radyoloji metinlerini birleştirir, muayene notlarını aktarır."},{name:"6. Uzmanlık Kategorizasyonu (categorize_specialty.js)",command:"node categorize_specialty.js",description:"Muayene kayıtlarını branş kodlarına göre işaretler."},{name:"7. Laboratuvar Metadata (migrate_lab_metadata.js)",command:"node migrate_lab_metadata.js",description:"Laboratuvar test tanımlarını ve referans aralıklarını aktarır."},{name:"8. Laboratuvar Sonuçları (migrate_lab_data.js)",command:"node migrate_lab_data.js",description:"Detaylı laboratuvar sonuçlarını aktarır."},{name:"9. Dosya Migrasyonu (migrate_files.js)",command:"node migrate_files.js",description:"Hasta dosyalarını ve radyoloji raporlarını aktarır."},{name:"10. Ödeme Migrasyonu (migrate_payments.js)",command:"node migrate_payments.js",description:"Finansal kayıtları ve ödemeleri aktarır."},{name:"11. Blind Index Migrasyonu (migrate_blind_index.php)",command:"php migrate_blind_index.php",description:"Şifreli hasta verileri için arama endekslerini oluşturur."}];for(let a=0;a<steps.length;a++){const e=steps[a];try{execSync(e.command,{stdio:"inherit",cwd:MIGRATION_ROOT,timeout:6e5})}catch(a){a.signal,a.stderr,process.exit(1)}}